example.code:
use atomic_capsule::collections::ConcurrentMapCapsule;

let map: ConcurrentMapCapsule<String, i32> = ConcurrentMapCapsule::new();

// Insert
map.insert("key1".to_string(), 100);
map.insert("key2".to_string(), 200);

// Get
assert_eq!(map.get("key1"), Some(&100));
assert_eq!(map.len(), 2);

// Remove
let old = map.remove("key1");
assert_eq!(old, Some(100));
assert_eq!(map.len(), 1);

use atomic_capsule::collections::ConcurrentMapCapsule;

let counters: ConcurrentMapCapsule<String, u64> = ConcurrentMapCapsule::new();

// Increment counter, inserting 0 if not present
fn increment(map: &ConcurrentMapCapsule<String, u64>, key: &str) {
    map.entry(key.to_string())
       .and_modify(|v| *v += 1)
       .or_insert(1);
}

use atomic_capsule::collections::ConcurrentMapCapsule;
use std::sync::Arc;

#[derive(Clone)]
struct Session {
    user_id: u64,
    created_at: u64,
}

// Shared session store
let sessions: Arc<ConcurrentMapCapsule<String, Session>> =
    Arc::new(ConcurrentMapCapsule::new());

// On login
sessions.insert(session_id.clone(), Session {
    user_id: 12345,
    created_at: timestamp(),
});

// On request
if let Some(session) = sessions.get(&session_id) {
    println!("User: {}", session.user_id);
}

// On logout
sessions.remove(&session_id);
